<!--vbase-->
<template>
  <div class="container p-b-0 settings">
    <div class="q-mt-md">
      <TrainingList
        :doc_type_key="doc_type_key"
        :doc_type="doc_type"
        :language_origin_list="language_origins"
        :max_value="training_doc_limit"
        :list_data="sample_files"
        :total_exported="trained_docs_count.org_exported_documents"
        :total_trained_by_org="trained_docs_count.org_trained_documents"
        :total_trained="trained_docs_count.total_trained_documents"
      />
    </div>
  </div>

  <q-inner-loading
    :showing="processing || language_origins_loading"
    class="z-index-1"
  >
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { useLangOriginDropdownStore } from 'src/store/main';
import TrainingList from 'src/pages/Settings/Components/ModelTraining/TrainingList.vue';
import { storeToRefs } from 'pinia';
import { isEmptyString } from 'src/utils/general';
import { documentDetailApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
export default defineComponent({
  el: '#app',
    components: {
    TrainingList,
  },
  mounted() {
    this.init();
    document.addEventListener('refresh_sample_data', this.refreshSampleData);
    document.addEventListener('sample_file_delete', this.sampleFileDeleted);
  },
  unmounted: function () {
    document.removeEventListener('refresh_sample_data', this.refreshSampleData);
    document.removeEventListener('sample_file_delete', this.sampleFileDeleted);
  },
  methods: {
    async init() {
      try {
        this.processing = true;
        this.doc_type_key = String(this.$route.params.doc_key);
        this.doc_type = String(this.$route.params.doc_type);
        await this.getLanguageIfEmpty();
        await this.fetchSamplesFiles();
        await this.fetchTrainedDocCount();
      } catch (err) {
      } finally {
        this.processing = false;
      }
    },

    refreshSampleData() {
      this.fetchSamplesFiles();
      this.fetchTrainedDocCount();
    },

    sampleFileDeleted(e: any) {
      if (!e || !e.detail) {
        return;
      }

      let id = e.detail;
      for (let [index, col] of Object.entries(this.sample_files)) {
        const column = col as dynamicObj;
        if (column.id === id) {
          this.sample_files.splice(index, 1);
        }
      }

      this.fetchTrainedDocCount();
    },

    async fetchSamplesFiles() {
      try {
        if (isEmptyString(this.doc_type_key)) {
          return;
        }

        const form_data = { doc_type: this.doc_type_key };
        const response =
          await documentDetailApiService.getModelTrainingSamplesFiles(
            form_data,
          );
        if (
          !response ||
          (response.hasOwnProperty('success') && response.success === false)
        ) {
          throw response;
        }

        let data = [];
        for (let [index, col] of Object.entries(response)) {
          const column = col as dynamicObj;
          let newRow: dynamicObj = { ...column };
          data.push(newRow);
        }
        this.sample_files = data;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
      }
    },

    async fetchTrainedDocCount() {
      try {
        if (isEmptyString(this.doc_type_key)) {
          return;
        }

        const form_data = { doc_type: this.doc_type_key };
        const response =
          await documentDetailApiService.getTrainedDocCount(form_data);
        if (
          !response ||
          (response.hasOwnProperty('success') && response.success === false)
        ) {
          throw response;
        }
        if (response.length == 0) {
          return;
        }
        this.trained_docs_count = response[0];
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
      }
    },
  },
  setup() {
    const language_origin_dropdown = useLangOriginDropdownStore();
    const { getLanguageIfEmpty } = language_origin_dropdown;
    const { language_origins, language_origins_loading } = storeToRefs(
      language_origin_dropdown,
    );

    return {
      language_origins,
      language_origins_loading,
      getLanguageIfEmpty,
      doc_type_key: ref(''),
      doc_type: ref(''),
      training_doc_limit: 0,
      sample_files: ref([] as any),
      processing: ref(false),
      trained_docs_count: ref({
        org_exported_documents: 0,
        org_sample_documents: 0,
        org_trained_documents: 0,
        total_trained_documents: 0,
        doc_type: '',
      } as any),
    };
  },
});
</script>

